1	package edgefleet
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"time"
8		"unicode/utf8"
9	)
10	
11	// Heartbeat is one telemetry record reported by a node.
12	//
13	// JSON input uses snake_case field names:
14	//
15	//	node          string   node id (required, non-empty)
16	//	seq           integer  sequence number (required, > 0)
17	//	collected_at  string   RFC3339 with timezone, e.g. 2026-10-01T12:00:00+08:00 (required)
18	//	version       string   version (required, non-empty, valid Unicode text)
19	//	height        integer  block height (required, >= 0)
20	//	missed        integer  cumulative missed duties (required, >= 0)
21	type Heartbeat struct {
22		NodeID      string    `json:"node"`
23		Seq         int64     `json:"seq"`
24		CollectedAt time.Time `json:"collected_at"`
25		Version     string    `json:"version"`
26		Height      int64     `json:"height"`
27		Missed      int64     `json:"missed"`
28	}
29	
30	// heartbeatFields enumerates every field that must be explicitly provided.
31	var heartbeatFields = []string{"node", "seq", "collected_at", "version", "height", "missed"}
32	
33	// fieldIssue classifies the way a field value violates a rule. Together with
34	// the field name and the offending numeric value it identifies the rule that
35	// failed, without carrying any wording. Each trust boundary renders the
36	// failure in its own message style and locates it in its own context, but the
37	// rules themselves — which values are legal — live in the check* functions
38	// below exactly once.
39	type fieldIssue int
40	
41	const (
42		issueEmpty          fieldIssue = iota // a required string is ""
43		issueInvalidUnicode                   // node id or version is not lossless text
44		issueNotPositive                      // integer must be > 0
45		issueNegative                         // integer must be >= 0
46		issueMissingInstant                   // collected_at is the zero instant
47	)
48	
49	// fieldValueError names the field whose value rule was violated.
50	type fieldValueError struct {
51		field string
52		issue fieldIssue
53		value int64
54	}
55	
56	// checkNodeIDValue holds the single node-id value rule: non-empty, valid
57	// Unicode text. The raw-JSON boundary additionally checks the un-decoded
58	// token (see validateRawText); for a value already decoded from such a
59	// token the Unicode branch can never fire, but both submit entries and the
60	// stored-data read enforce the same rule through this one function.
61	func checkNodeIDValue(node string) *fieldValueError {
62		if node == "" {
63			return &fieldValueError{field: "node", issue: issueEmpty}
64		}
65		if !utf8.ValidString(node) {
66			return &fieldValueError{field: "node", issue: issueInvalidUnicode}
67		}
68		return nil
69	}
70	
71	// checkVersionValue holds the single version value rule: non-empty, valid
72	// Unicode text. The version is opaque text — Chinese, emoji and a literal "�"
73	// the user typed are all legal, and no format (digits and dots) is imposed —
74	// but it must be losslessly representable: a platform that silently rewrites
75	// invalid bytes to U+FFFD would merge distinct versions into one and make the
76	// version-skew judgement compare text the node never reported. The raw-JSON
77	// boundary additionally checks the un-decoded token (see validateRawText);
78	// for a value already decoded from such a token the Unicode branch can never
79	// fire, but both submit entries and the stored-data read enforce the same
80	// rule through this one function.
81	func checkVersionValue(version string) *fieldValueError {
82		if version == "" {
83			return &fieldValueError{field: "version", issue: issueEmpty}
84		}
85		if !utf8.ValidString(version) {
86			return &fieldValueError{field: "version", issue: issueInvalidUnicode}
87		}
88		return nil
89	}
90	
91	// checkPositiveInt holds the single positive-integer rule (seq).
92	func checkPositiveInt(field string, value int64) *fieldValueError {
93		if value <= 0 {
94			return &fieldValueError{field: field, issue: issueNotPositive, value: value}
95		}
96		return nil
97	}
98	
99	// checkNonNegativeInt holds the single non-negative-integer rule (height,
100	// missed). An explicit zero is genuine telemetry and passes.
101	func checkNonNegativeInt(field string, value int64) *fieldValueError {
102		if value < 0 {
103			return &fieldValueError{field: field, issue: issueNegative, value: value}
104		}
105		return nil
106	}
107	
108	// checkCollectedAtValue holds the single rule that a collection instant must
109	// actually be present (not the zero time).
110	func checkCollectedAtValue(collected time.Time) *fieldValueError {
111		if collected.IsZero() {
112			return &fieldValueError{field: "collected_at", issue: issueMissingInstant}
113		}
114		return nil
115	}
116	
117	// checkHeartbeatValues runs every context-free field-value rule in the single
118	// rejection order shared by the direct-submit and stored-data boundaries:
119	// node, seq, version, height, missed, then collected_at. It deliberately does
120	// NOT compare against a receive time: reading saved history has no receive
121	// time, and that submit-only rule lives in checkCollectedAtTiming.
122	func checkHeartbeatValues(h Heartbeat) *fieldValueError {
123		if e := checkNodeIDValue(h.NodeID); e != nil {
124			return e
125		}
126		if e := checkPositiveInt("seq", h.Seq); e != nil {
127			return e
128		}
129		if e := checkVersionValue(h.Version); e != nil {
130			return e
131		}
132		if e := checkNonNegativeInt("height", h.Height); e != nil {
133			return e
134		}
135		if e := checkNonNegativeInt("missed", h.Missed); e != nil {
136			return e
137		}
138		return checkCollectedAtValue(h.CollectedAt)
139	}
140	
141	// checkCollectedAtTiming holds the single receive-time rule, which belongs to
142	// submission only: a collection time later than the receive time is refused;
143	// the same instant expressed in another timezone is equal and allowed. The
144	// stored-data read path never calls this, so reading history introduces no
145	// current time and no extra time limit.
146	func checkCollectedAtTiming(collected, receiveTime time.Time) error {
147		if collected.After(receiveTime) {
148			return fmt.Errorf("collected_at %s is later than receive time %s",
149				collected.Format(time.RFC3339), receiveTime.Format(time.RFC3339))
150		}
151		return nil
152	}
153	
154	// directError renders a field rule failure in ValidateHeartbeat's wording,
155	// used when a caller submits an already constructed Heartbeat.
156	func (e *fieldValueError) directError() error {
157		switch {
158		case e.field == "node" && e.issue == issueEmpty:
159			return fmt.Errorf("node id is empty")
160		case e.field == "node" && e.issue == issueInvalidUnicode:
161			return fmt.Errorf("node id is not valid Unicode text: contains invalid UTF-8")
162		case e.field == "seq":
163			return fmt.Errorf("seq must be a positive integer, got %d", e.value)
164		case e.field == "version" && e.issue == issueInvalidUnicode:
165			return fmt.Errorf("version is not valid Unicode text: contains invalid UTF-8")
166		case e.field == "version":
167			return fmt.Errorf("version is empty")
168		case e.field == "height":
169			return fmt.Errorf("height must be >= 0, got %d", e.value)
170		case e.field == "missed":
171			return fmt.Errorf("missed must be >= 0, got %d", e.value)
172		case e.field == "collected_at":
173			return fmt.Errorf("collected_at is missing or invalid")
174		default:
175			return fmt.Errorf("field %q has an invalid value", e.field)
176		}
177	}
178	
179	// decodeError renders a field rule failure in the wording used while decoding
180	// a strict JSON object (submit input and stored records alike).
181	func (e *fieldValueError) decodeError() error {
182		switch {
183		case e.field == "node" && e.issue == issueInvalidUnicode:
184			return fmt.Errorf("node id is not valid Unicode text: contains invalid UTF-8")
185		case e.field == "node":
186			return fmt.Errorf("node must not be empty")
187		case e.field == "seq":
188			return fmt.Errorf("seq must be a positive integer, got %d", e.value)
189		case e.field == "version" && e.issue == issueInvalidUnicode:
190			return fmt.Errorf("version is not valid Unicode text: contains invalid UTF-8")
191		case e.field == "version":
192			return fmt.Errorf("version must not be empty")
193		case e.field == "height":
194			return fmt.Errorf("height must be >= 0, got %d", e.value)
195		case e.field == "missed":
196			return fmt.Errorf("missed must be >= 0, got %d", e.value)
197		default:
198			return fmt.Errorf("invalid value for field %q", e.field)
199		}
200	}
201	
202	// storedError renders a field rule failure for a record read from a saved
203	// file, prefixing the 1-based record position as stored-data errors do.
204	func (e *fieldValueError) storedError(position int) error {
205		switch {
206		case (e.field == "node" || e.field == "version") && e.issue == issueInvalidUnicode:
207			return fmt.Errorf("record %d: field %q is not valid Unicode text", position, e.field)
208		case e.field == "node" || e.field == "version":
209			return fmt.Errorf("record %d: field %q must not be empty", position, e.field)
210		case e.field == "seq":
211			return fmt.Errorf("record %d: field %q must be a positive integer, got %d", position, e.field, e.value)
212		case e.field == "height" || e.field == "missed":
213			return fmt.Errorf("record %d: field %q must be >= 0, got %d", position, e.field, e.value)
214		case e.field == "collected_at":
215			return fmt.Errorf("record %d: field %q is missing or invalid", position, e.field)
216		default:
217			return fmt.Errorf("record %d: field %q has an invalid value", position, e.field)
218		}
219	}
220	
221	// ValidateHeartbeat checks the semantic rules for one record. receiveTime is
222	// the moment the platform received the batch; a collection time later than
223	// receive time is rejected. The field-value rules are shared with JSON
224	// parsing and the stored-file read path via checkHeartbeatValues; only the
225	// receive-time comparison is submit-specific.
226	func ValidateHeartbeat(h Heartbeat, receiveTime time.Time) error {
227		if e := checkHeartbeatValues(h); e != nil {
228			return e.directError()
229		}
230		return checkCollectedAtTiming(h.CollectedAt, receiveTime)
231	}
232	
233	// Equal reports whether two records are the same telemetry. Collection times
234	// are compared as instants, so the same moment expressed in different
235	// timezones compares equal.
236	func (h Heartbeat) Equal(o Heartbeat) bool {
237		return h.NodeID == o.NodeID &&
238			h.Seq == o.Seq &&
239			h.Version == o.Version &&
240			h.Height == o.Height &&
241			h.Missed == o.Missed &&
242			h.CollectedAt.Equal(o.CollectedAt)
243	}
244	
245	// ParseHeartbeats parses a JSON array of heartbeat objects. Every field must
246	// be explicitly provided; missing or unknown fields are rejected with a
247	// specific reason.
248	func ParseHeartbeats(data []byte, receiveTime time.Time) ([]Heartbeat, error) {
249		var raw []json.RawMessage
250		if err := json.Unmarshal(data, &raw); err != nil {
251			return nil, fmt.Errorf("input must be a JSON array of heartbeat objects: %w", err)
252		}
253		if len(raw) == 0 {
254			return nil, fmt.Errorf("no heartbeat records provided")
255		}
256		records := make([]Heartbeat, 0, len(raw))
257		for i, r := range raw {
258			h, err := parseOneHeartbeat(r, receiveTime)
259			if err != nil {
260				return nil, fmt.Errorf("record %d: %w", i+1, err)
261			}
262			records = append(records, h)
263		}
264		return records, nil
265	}
266	
267	// rejectNull reports an error when a required field's JSON value is null.
268	// A null value means the node did not report the field, which must not be
269	// silently saved as the zero value.
270	func rejectNull(raw json.RawMessage, field string) error {
271		if bytes.Equal(raw, []byte("null")) {
272			return fmt.Errorf("%s must not be null", field)
273		}
274		return nil
275	}
276	
277	// objectFields collects the fields of one JSON object while enforcing the
278	// single field-uniqueness rule shared by every strict decoder in this
279	// package: within one object, a field name may appear only once. Names are
280	// compared as the JSON strings they decode to, so a plain spelling and a
281	// Unicode-escaped spelling of the same name collide, whether the repeated
282	// value is identical or different. The rule is scoped to the current object:
283	// the same field name appearing in another heartbeat object is unrelated.
284	// Both the submit-input decoder (decodeStrictHeartbeatObject) and the
285	// stored-file envelope decoder (decodeStrictNodeFile) apply the rule through
286	// this type; each boundary keeps its own error wording and its own check
287	// ordering for the rejection.
288	//
289	// A nil map value means the name has been seen but its value not decoded
290	// yet; once decoded, the value is stored under the name.
291	type objectFields map[string]json.RawMessage
292	
293	// check records one occurrence of a field name and reports whether the name
294	// already appeared in this object (duplicate == true).
295	func (o objectFields) check(name string) (duplicate bool) {
296		if _, exists := o[name]; exists {
297			return true
298		}
299		o[name] = nil
300		return false
301	}
302	
303	// has reports whether the field name appeared in this object.
304	func (o objectFields) has(name string) bool {
305		_, exists := o[name]
306		return exists
307	}
308	
309	// decodeStrictHeartbeatObject converts one JSON object's raw bytes into a
310	// Heartbeat while enforcing the field rules at every trust boundary: all
311	// fields must be present and non-null, unknown fields are rejected, and a
312	// field may never appear twice in the same object — even with the same
313	// value, and even when one spelling uses a JSON Unicode escape denoting the
314	// same key (the shared objectFields rule). A plain struct/map unmarshal
315	// would instead keep the last
316	// occurrence and let an absent field masquerade as the zero value. Both the
317	// submit input path and the stored-file read path must use it.
318	func decodeStrictHeartbeatObject(raw json.RawMessage) (Heartbeat, error) {
319		// Walk the object with a streaming decoder so duplicate field names are
320		// detected. Field names are compared as the JSON string they represent:
321		// "missed" and "m\u0069ssed" are the same field. A map-based unmarshal
322		// would silently keep only the last occurrence.
323		dec := json.NewDecoder(bytes.NewReader(raw))
324		tok, err := dec.Token()
325		if err != nil {
326			return Heartbeat{}, fmt.Errorf("record must be a JSON object: %w", err)
327		}
328		if d, ok := tok.(json.Delim); !ok || d != '{' {
329			return Heartbeat{}, fmt.Errorf("record must be a JSON object")
330		}
331	
332		fields := objectFields{}
333		for dec.More() {
334			keyTok, err := dec.Token()
335			if err != nil {
336				return Heartbeat{}, fmt.Errorf("invalid field: %w", err)
337			}
338			key, ok := keyTok.(string)
339			if !ok {
340				return Heartbeat{}, fmt.Errorf("field name must be a string")
341			}
342			if fields.check(key) {
343				return Heartbeat{}, fmt.Errorf("duplicate field %q", key)
344			}
345			var val json.RawMessage
346			if err := dec.Decode(&val); err != nil {
347				return Heartbeat{}, fmt.Errorf("invalid value for field %q: %w", key, err)
348			}
349			fields[key] = val
350		}
351		// Consume the closing brace.
352		if _, err := dec.Token(); err != nil {
353			return Heartbeat{}, fmt.Errorf("invalid record: %w", err)
354		}
355	
356		for _, f := range heartbeatFields {
357			if !fields.has(f) {
358				return Heartbeat{}, fmt.Errorf("missing required field %q", f)
359			}
360		}
361		for k := range fields {
362			if !containsString(heartbeatFields, k) {
363				return Heartbeat{}, fmt.Errorf("unknown field %q", k)
364			}
365		}
366	
367		var h Heartbeat
368	
369		if err := rejectNull(fields["node"], "node"); err != nil {
370			return Heartbeat{}, err
371		}
372		if err := json.Unmarshal(fields["node"], &h.NodeID); err != nil {
373			return Heartbeat{}, fmt.Errorf("node must be a string: %w", err)
374		}
375		if err := validateRawText(fields["node"], "node"); err != nil {
376			return Heartbeat{}, err
377		}
378		if e := checkNodeIDValue(h.NodeID); e != nil {
379			return Heartbeat{}, e.decodeError()
380		}
381	
382		if err := rejectNull(fields["seq"], "seq"); err != nil {
383			return Heartbeat{}, err
384		}
385		if err := json.Unmarshal(fields["seq"], &h.Seq); err != nil {
386			return Heartbeat{}, fmt.Errorf("seq must be an integer: %w", err)
387		}
388		if e := checkPositiveInt("seq", h.Seq); e != nil {
389			return Heartbeat{}, e.decodeError()
390		}
391	
392		if err := rejectNull(fields["collected_at"], "collected_at"); err != nil {
393			return Heartbeat{}, err
394		}
395		var collectedStr string
396		if err := json.Unmarshal(fields["collected_at"], &collectedStr); err != nil {
397			return Heartbeat{}, fmt.Errorf("collected_at must be a string: %w", err)
398		}
399		t, err := time.Parse(time.RFC3339, collectedStr)
400		if err != nil {
401			return Heartbeat{}, fmt.Errorf("collected_at must be RFC3339 with timezone (e.g. 2026-10-01T12:00:00+08:00): %w", err)
402		}
403		h.CollectedAt = t
404	
405		if err := rejectNull(fields["version"], "version"); err != nil {
406			return Heartbeat{}, err
407		}
408		if err := json.Unmarshal(fields["version"], &h.Version); err != nil {
409			return Heartbeat{}, fmt.Errorf("version must be a string: %w", err)
410		}
411		if err := validateRawText(fields["version"], "version"); err != nil {
412			return Heartbeat{}, err
413		}
414		if e := checkVersionValue(h.Version); e != nil {
415			return Heartbeat{}, e.decodeError()
416		}
417	
418		if err := rejectNull(fields["height"], "height"); err != nil {
419			return Heartbeat{}, err
420		}
421		if err := json.Unmarshal(fields["height"], &h.Height); err != nil {
422			return Heartbeat{}, fmt.Errorf("height must be an integer: %w", err)
423		}
424		if e := checkNonNegativeInt("height", h.Height); e != nil {
425			return Heartbeat{}, e.decodeError()
426		}
427	
428		if err := rejectNull(fields["missed"], "missed"); err != nil {
429			return Heartbeat{}, err
430		}
431		if err := json.Unmarshal(fields["missed"], &h.Missed); err != nil {
432			return Heartbeat{}, fmt.Errorf("missed must be an integer: %w", err)
433		}
434		if e := checkNonNegativeInt("missed", h.Missed); e != nil {
435			return Heartbeat{}, e.decodeError()
436		}
437	
438		return h, nil
439	}
440	
441	// validateRawText checks the raw JSON string token of a text field (node or
442	// version) before its decoded value is trusted. encoding/json silently rewrites
443	// invalid UTF-8 bytes and unpaired \u surrogate escapes to U+FFFD, which
444	// would merge distinct texts into one replacement-char value: distinct node
445	// ids would collapse and break the ownership check against stored files, and
446	// distinct versions would collapse into text the node never reported,
447	// corrupting dedup and the version-skew judgement. The raw token must decode
448	// losslessly: every literal byte sequence must be valid UTF-8, and every \u
449	// escape must be a valid scalar value or a properly paired high/low
450	// surrogate pair. A literal "�" (or its \uFFFD escape) is valid text the
451	// user typed and is accepted; only undecodable input is rejected. A \\
452	// escape is consumed as a unit, so text that genuinely contains a backslash
453	// followed by "u" and hex digits is never re-interpreted as an escape.
454	func validateRawText(raw json.RawMessage, field string) error {
455		raw = bytes.TrimSpace(raw)
456		if len(raw) < 2 || raw[0] != '"' || raw[len(raw)-1] != '"' {
457			return fmt.Errorf("%s must be a string", field)
458		}
459		s := raw[1 : len(raw)-1]
460		for i := 0; i < len(s); {
461			c := s[i]
462			if c == '\\' {
463				if i+1 >= len(s) {
464					return fmt.Errorf("%s contains a truncated escape", field)
465				}
466				if s[i+1] != 'u' {
467					i += 2
468					continue
469				}
470				if i+6 > len(s) {
471					return fmt.Errorf("%s contains a truncated \\u escape", field)
472				}
473				r, err := parseHex4(s[i+2 : i+6])
474				if err != nil {
475					return fmt.Errorf("%s contains an invalid \\u escape: %w", field, err)
476				}
477				switch {
478				case r >= 0xD800 && r <= 0xDBFF:
479					// A high surrogate is only valid when immediately followed
480					// by a low-surrogate \u escape.
481					if i+12 > len(s) || s[i+6] != '\\' || s[i+7] != 'u' {
482						return fmt.Errorf("%s contains an unpaired high surrogate \\u%04X", field, r)
483					}
484					lo, err := parseHex4(s[i+8 : i+12])
485					if err != nil {
486						return fmt.Errorf("%s contains an invalid \\u escape: %w", field, err)
487					}
488					if lo < 0xDC00 || lo > 0xDFFF {
489						return fmt.Errorf("%s contains an unpaired high surrogate \\u%04X", field, r)
490					}
491					i += 12
492				case r >= 0xDC00 && r <= 0xDFFF:
493					return fmt.Errorf("%s contains an unpaired low surrogate \\u%04X", field, r)
494				default:
495					i += 6
496				}
497				continue
498			}
499			if c < utf8.RuneSelf {
500				i++
501				continue
502			}
503			// A valid multi-byte rune decodes with size >= 2; size 1 means the
504			// bytes are not valid UTF-8 (including surrogate encodings).
505			_, size := utf8.DecodeRune(s[i:])
506			if size == 1 {
507				return fmt.Errorf("%s contains invalid UTF-8 at byte offset %d", field, i)
508			}
509			i += size
510		}
511		return nil
512	}
513	
514	// parseHex4 parses exactly four hexadecimal digits as a 16-bit value.
515	func parseHex4(b []byte) (rune, error) {
516		v := 0
517		for _, c := range b {
518			var d int
519			switch {
520			case '0' <= c && c <= '9':
521				d = int(c - '0')
522			case 'a' <= c && c <= 'f':
523				d = int(c-'a') + 10
524			case 'A' <= c && c <= 'F':
525				d = int(c-'A') + 10
526			default:
527				return 0, fmt.Errorf("invalid hex digit %q", c)
528			}
529			v = v*16 + d
530		}
531		return rune(v), nil
532	}
533	
534	// parseOneHeartbeat decodes one submit-input record and applies the
535	// submit-only rule that collection time cannot be later than receive time.
536	func parseOneHeartbeat(raw json.RawMessage, receiveTime time.Time) (Heartbeat, error) {
537		h, err := decodeStrictHeartbeatObject(raw)
538		if err != nil {
539			return Heartbeat{}, err
540		}
541		if err := checkCollectedAtTiming(h.CollectedAt, receiveTime); err != nil {
542			return Heartbeat{}, err
543		}
544		return h, nil
545	}
546	
547	func containsString(list []string, s string) bool {
548		for _, v := range list {
549			if v == s {
550				return true
551			}
552		}
553		return false
554	}
