31		"testing"
32	)
33	
34	const (
35		// cliTestEnv makes the re-executed test binary run the real main() instead
36		// of the test suite.
37		cliTestEnv = "EDGEFLEET_CLI_TEST_HELPER_PROCESS"
38	
39		// Fixed instants: heartbeats arrive and are queried at known times, so
40		// online status is deterministic without sleeping.
41		cliReceiveAt = "2026-10-01T12:00:00Z"
42		cliQueryAt   = "2026-10-01T12:00:00Z"
43	)
