766	// TestCLISubmitMixedBatchCountsNewAndDuplicate drives the example rule end to
767	// end: a batch may mix records already saved, exact repeats within the same
768	// batch, and new records for other nodes. new counts only records genuinely
769	// added this time; duplicate counts every input record that added nothing.
770	// The same seq used by different nodes is never deduplicated across nodes.
771	func TestCLISubmitMixedBatchCountsNewAndDuplicate(t *testing.T) {
772		dir := t.TempDir()
773	
774		// 甲 already has seq 1 saved.
775		submitBatch(t, dir, `[
776		  {"node":"甲","seq":1,"collected_at":"2026-10-01T11:59:00Z","version":"1.26.0","height":100,"missed":0}
777		]`)
778	
779		// Batch: 甲 seq1 again verbatim (duplicate against history), 甲 seq2 twice
780		// identical (one new, one duplicate within the batch), 乙 seq2 (new). The
781		// two nodes share seq 2 but stay distinct records.
782		out, errOut, code := submit(t, dir, `[
783		  {"node":"甲","seq":1,"collected_at":"2026-10-01T11:59:00Z","version":"1.26.0","height":100,"missed":0},
784		  {"node":"甲","seq":2,"collected_at":"2026-10-01T11:59:30Z","version":"1.26.0","height":101,"missed":0},
785		  {"node":"甲","seq":2,"collected_at":"2026-10-01T11:59:30Z","version":"1.26.0","height":101,"missed":0},
786		  {"node":"乙","seq":2,"collected_at":"2026-10-01T11:59:30Z","version":"1.26.0","height":201,"missed":2}
787		]`)
788		if code != 0 {
789			t.Fatalf("mixed batch must succeed, exit=%d stderr=%q", code, errOut)
790		}
791		if errOut != "" {
792			t.Errorf("a successful submit must leave stderr empty, got %q", errOut)
793		}
794		if strings.TrimRight(out, "\n") != "submitted: new=2 duplicate=2" {
795			t.Errorf("stdout = %q, want submitted: new=2 duplicate=2", out)
796		}
797	
798		// 甲 history: exactly seq 1 and 2, ascending, original seq-1 telemetry
799		// untouched and seq-2 content as submitted.
800		jia := historyLines(t, dir, "甲")
801		if len(jia) != 2 {
802			t.Fatalf("甲 history = %q, want exactly two records", jia)
803		}
804		want1 := "node=甲 seq=1 collected_at=2026-10-01T11:59:00Z version=1.26.0 height=100 missed=0"
805		want2 := "node=甲 seq=2 collected_at=2026-10-01T11:59:30Z version=1.26.0 height=101 missed=0"
806		if jia[0] != want1 {
807			t.Errorf("甲 first line = %q, want %q", jia[0], want1)
808		}
809		if jia[1] != want2 {
810			t.Errorf("甲 second line = %q, want %q", jia[1], want2)
811		}
812	
813		// 乙 has only its own seq 2; same seq number as 甲 did not dedup.
814		yi := historyLines(t, dir, "乙")
815		if len(yi) != 1 {
816			t.Fatalf("乙 history = %q, want exactly one record", yi)
817		}
818		wantYi := "node=乙 seq=2 collected_at=2026-10-01T11:59:30Z version=1.26.0 height=201 missed=2"
819		if yi[0] != wantYi {
820			t.Errorf("乙 line = %q, want %q", yi[0], wantYi)
821		}
822	}
